content.content:
{
 "type": "object",
 "required": [
  "itineraryId"
 ],
 "properties": {
  "itineraryId": {
   "type": "string",
   "description": "Itinerary to confirm."
  },
  "paymentType": {
   "$ref": "#/components/schemas/PaymentType",
   "default": "full",
   "description": "Must match the PaymentIntent. Defaults to `full` when omitted so `{ \"itineraryId\" }` still confirms a full payment."
  },
  "planIndex": {
   "type": "integer",
   "minimum": 0,
   "description": "Same installment index used when creating the PaymentIntent (`0` = deposit)."
  },
  "paymentIntentId": {
   "type": "string",
   "description": "Stripe PaymentIntent id (`pi_...`) from the confirmed payment. Optional; forwarded to the brand site when present."
  },
  "paymentStatus": {
   "type": "string",
   "description": "Stripe PaymentIntent status after confirmation (e.g. `succeeded`). Optional; forwarded to the brand site when present."
  }
 }
}
{
 "200": {
  "description": "Reservation upserted",
  "content": {
   "application/json": {
    "schema": {
     "type": "object",
     "required": [
      "data"
     ],
     "properties": {
      "data": {
       "type": "string",
       "description": "Reservation code (e.g. `R-12345`)."
      },
      "meta": {
       "type": "object",
       "properties": {
        "now": {
         "type": "integer",
         "description": "Upstream clock (epoch ms) \u2014 forwarded from the brand site."
        }
       }
      }
     }
    }
   }
  }
 },
 "400": {
  "$ref": "#/components/responses/Problem"
 },
 "401": {
  "$ref": "#/components/responses/Problem"
 },
 "403": {
  "$ref": "#/components/responses/Problem"
 },
 "429": {
  "$ref": "#/components/responses/Problem"
 },
 "502": {
  "$ref": "#/components/responses/Problem"
 }
}
"Return the full cart snapshot for an itinerary (checkout totals, activities, accommodation, customer, pax, tracking commerce). Internal clients only."
1.0.0 Public HTTP API for House of Journeys content distribution. Authenticate with API keys or OAuth2 client credentials. Responses follow House of Journeys DTOs; upstream CMS details are not part of the public contract.
